<script lang="ts">import {onMount} from 'svelte';import PhotoImage from '$lib/components/PhotoImage.svelte';import {dateLabel} from '$lib/format';let{data}=$props();function keys(e:KeyboardEvent){let target:string|null=null;if(e.key==='Escape')target='/photos';if(e.key==='ArrowLeft'&&data.previous)target=`/photos/${data.previous}`;if(e.key==='ArrowRight'&&data.next)target=`/photos/${data.next}`;if(target){e.preventDefault();window.location.assign(target);}}onMount(()=>{window.addEventListener('keydown',keys);document.querySelector<HTMLElement>('.lightbox .close')?.focus();return()=>window.removeEventListener('keydown',keys);});</script><svelte:head><title>{data.photo.caption??'Photo'} — Westin Perry</title></svelte:head><section class="detail-page"><div class="lightbox" role="dialog" aria-modal="true" aria-label="Photo viewer"><a class="close" href="/photos" aria-label="Close photo viewer">Close ×</a><figure><PhotoImage photo={data.photo} eager/><figcaption><time datetime={data.photo.display_date?new Date(data.photo.display_date).toISOString():undefined}>{dateLabel(data.photo.display_date)}</time>{#if data.photo.caption}<h1 style="font-size:2.4rem;margin-top:1rem">{data.photo.caption}</h1>{/if}{#if data.photo.note}<p>{data.photo.note}</p>{/if}{#if data.photo.place}<p class="meta">{data.photo.place}</p>{/if}{#if data.photo.album_name}<p class="meta">Album — {data.photo.album_name}</p>{/if}</figcaption></figure><nav class="lightbox-nav">{#if data.previous}<a href={`/photos/${data.previous}`}>← Previous</a>{:else}<span></span>{/if}{#if data.next}<a href={`/photos/${data.next}`}>Next →</a>{/if}</nav></div></section>
